"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[97541],{6519:e=>{e.exports=JSON.parse('{"functions":[{"name":"start","desc":"Runs one shell-turret weapon: `Config` is its config module (BurstCannonConfig\\nfield set), `packets` its own packets.","params":[{"name":"Config","desc":"","lua_type":"any"},{"name":"packets","desc":"","lua_type":"ShellPackets"}],"returns":[],"function_type":"static","source":{"line":93,"path":"src/ServerStorage/SharedModules/ShellTurretServer.luau"}}],"properties":[],"types":[{"name":"ShellPackets","desc":"The weapon\'s own packets (same shapes as the BurstCannon ones). Heat mode has\\nno `Reload`; no-splash shots need `Impact` (hit position).","lua_type":"{ Mount: any, Trigger: any, Aim: any, Reload: any?, Fired: any, Impact: any? }","source":{"line":60,"path":"src/ServerStorage/SharedModules/ShellTurretServer.luau"}}],"name":"ShellTurretServer","desc":"The shared weapon layer of the shell-firing train turrets (Cannon, Burst\\nCannon, AutoCannon, Energy Cannon). `start(Config, packets)` runs one weapon on the shared turret core\\n(`TrainTurretServer`), which discovers placed turrets in\\nworkspace.PlacedObjects, seats the gunner after validation (and ejects anyone\\nit did not seat) and steps the yaw/pitch toward the gunner\'s aim reports at\\nthe turn-rate limit. This module adds the magazine and reload, and FastCast2\\nspherecast shells fired from the turret\'s own rig math in bursts of\\n`BurstSize` (`BurstSize = 1` is plain full-auto). A proximity fuse and a direct\\nhit both give the target full damage (`TrainWeaponDamage.applyDirect`) before\\nthe splash (`applyBlast`). State is published as attributes on the placed\\nModel: AimYaw, AimPitch, Ammo, Reloading, ReloadEndsAt, GunnerUserId, plus the\\nHUD contract DisplayName, MagazineSize, ReloadTime (read by the generic\\nTurretGui).\\n\\nWith no gunner for `CannonConfig.AutoLoaderIdleTime` and a Smart Cannon /\\nOrbital Sentinel holder in the party, the turret aims at the nearest visible\\nenemy itself and fires at `AutoLoaderRate` x the manned cadence, credited to\\nthe holder. A started burst finishes after the trigger is released.\\n\\n**Heat mode** (Energy Cannon: `Config.HeatPerShot` is set) replaces the\\nmagazine and reload with `EnergyCannonMath` heat: each shot adds heat, the\\nshot that reaches max starts an overheat lock, and the turret publishes\\nHeat, Overheated, MaxHeat, PeakHeat instead of Ammo / MagazineSize (the\\nTurretGui heat mode). Unmanned fire keeps out of overheat with\\n`EnergyCannonMath.autoAllowed`. **No-splash shots** (`Config.BlastRadius == 0`)\\ndamage only what they hit (an enemy through `applyDirect`, a rock through\\n`RockService.Damage`) and broadcast `packets.Impact` instead of `ExplosionAt`.","realm":["Server"],"source":{"line":34,"path":"src/ServerStorage/SharedModules/ShellTurretServer.luau"}}')}}]);